-- Python project templates.

local function pyproject_cli(ctx)
  return table.concat({
    "[build-system]",
    'requires = ["setuptools>=68"]',
    'build-backend = "setuptools.build_meta"',
    "",
    "[project]",
    ('name = "%s"'):format(ctx.project_slug),
    'version = "0.1.0"',
    'description = "Generated by Scaffold.nvim"',
    'requires-python = ">=3.10"',
    "dependencies = []",
    "",
    "[project.scripts]",
    ('%s = "%s.cli:main"'):format(ctx.project_slug, ctx.project_module),
    "",
    "[tool.setuptools.packages.find]",
    'where = ["src"]',
    "",
    "[tool.pyright]",
    'venvPath = "."',
    'venv = ".venv"',
    "",
  }, "\n")
end

local function python_runtime(ctx)
  return ctx.selected_runtime or "python3"
end

local python_cli = {
  id = "python-cli",
  name = "Python CLI",
  language = "python",
  version = 1,
  description = "A src-layout Python package with an argparse CLI and unittest tests.",
  build_systems = { "pip" },
  package_managers = { "pip", "venv" },
  runtime_options = { "python3" },
  default_runtime = "python3",
  requires = { "python3" },
  options = {},
  files = {
    ["pyproject.toml"] = pyproject_cli,
    ["src/{{project_module}}/__init__.py"] = '__version__ = "0.1.0"\n',
    ["src/{{project_module}}/cli.py"] = table.concat({
      "import argparse",
      "",
      "",
      "def build_parser() -> argparse.ArgumentParser:",
      '    parser = argparse.ArgumentParser(prog="{{project_slug}}")',
      '    parser.add_argument("name", nargs="?", default="world")',
      "    return parser",
      "",
      "",
      "def main(argv: list[str] | None = None) -> int:",
      "    args = build_parser().parse_args(argv)",
      '    print(f"Hello, {args.name}!")',
      "    return 0",
      "",
      "",
      'if __name__ == "__main__":',
      "    raise SystemExit(main())",
      "",
    }, "\n"),
    ["src/{{project_module}}/__main__.py"] = table.concat({
      "from .cli import main",
      "",
      "raise SystemExit(main())",
      "",
    }, "\n"),
    ["tests/test_cli.py"] = table.concat({
      "import sys",
      "import unittest",
      "from pathlib import Path",
      "",
      'sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))',
      "",
      "from {{project_module}}.cli import build_parser, main",
      "",
      "",
      "class CliTests(unittest.TestCase):",
      "    def test_default_name(self):",
      '        self.assertEqual(build_parser().parse_args([]).name, "world")',
      "",
      "    def test_main_returns_zero(self):",
      "        self.assertEqual(main([]), 0)",
      "",
      "",
      'if __name__ == "__main__":',
      "    unittest.main()",
      "",
    }, "\n"),
    [".gitignore"] = table.concat({
      "__pycache__/",
      "*.py[cod]",
      ".venv/",
      "build/",
      "dist/",
      "*.egg-info/",
      ".pytest_cache/",
      "",
    }, "\n"),
    ["README.md"] = table.concat({
      "# {{project_name}}",
      "",
      "Python CLI generated by Scaffold.nvim.",
      "",
      "```sh",
      "python3 -m venv .venv",
      ".venv/bin/pip install -e .",
      ".venv/bin/python -m {{project_module}}",
      "```",
      "",
    }, "\n"),
  },
  commands = {
    run = function(ctx)
      return { python_runtime(ctx), "-m", ctx.project_module }
    end,
    test = function(ctx)
      return { python_runtime(ctx), "-m", "unittest", "discover", "-s", "tests", "-v" }
    end,
  },
  install_commands = function(ctx)
    return {
      { label = "Create virtual environment", argv = { python_runtime(ctx), "-m", "venv", ".venv" } },
      { label = "Install project in editable mode", argv = { ".venv/bin/pip", "install", "-e", "." } },
    }
  end,
}

